output_text:
[
  {
    "id": "cart_return_after_use",
    "text": "A shopper who takes the entry cart is obliged to return it to the northwest cart-return bay before leaving.",
    "abstraction": {
      "state_properties": {
        "entry_cart_bay": "at(1,5)",
        "northwest_cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "picked_up_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_bay",
              "cartAt(1,5)",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "returned_cart_to_nw_bay": {
          "pre": {
            "and": [
              "northwest_cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "picked_up_entry_cart",
      "discharge": "returned_cart_to_nw_bay"
    }
  },
  {
    "id": "cart_drop_only_at_return_bay",
    "text": "Carts may be put down only at the northwest cart-return bay.",
    "abstraction": {
      "state_properties": {
        "authorized_cart_drop_cell": "at(0,1)"
      },
      "events": {
        "cart_drop": {
          "pre": {
            "and": [
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_drop",
          {
            "not": "authorized_cart_drop_cell"
          }
        ]
      }
    }
  },
  {
    "id": "no_exit_while_pushing_cart",
    "text": "A shopper is forbidden from exiting the store while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "designated_exit_cell": "at(9,5)"
      },
      "events": {
        "exit_attempt": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_attempt",
          "pushing_cart"
        ]
      }
    }
  },
  {
    "id": "no_carts_in_exit_concourse",
    "text": "Carts are not allowed in the bottom exit concourse beyond the entry-cart area.",
    "abstraction": {
      "state_properties": {
        "exit_concourse": {
          "or": [
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_concourse",
          "pushing_cart"
        ]
      }
    }
  },
  {
    "id": "items_must_go_in_cart",
    "text": "Shelf items must be collected into a cart rather than carried by hand.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "item_taken_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "has_shopping_cart"
              }
            ]
          },
          "post": null
        },
        "item_taken_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "has_shopping_cart"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "item_taken_without_cart",
          "carrying_item_by_hand"
        ]
      }
    }
  },
  {
    "id": "take_available_entry_cart",
    "text": "When an entry cart is available at the start of the trip, the shopper is obliged to take it before continuing the shop.",
    "abstraction": {
      "state_properties": {
        "entry_cart_available": "cartAt(1,5)",
        "at_entry_cart": "at(1,5)"
      },
      "events": {
        "picked_up_entry_cart": {
          "pre": {
            "and": [
              "at_entry_cart",
              "entry_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "entry_cart_available",
      "discharge": "picked_up_entry_cart"
    }
  },
  {
    "id": "dairy_pickup_turns_back_west",
    "text": "After actually picking up an item from the dairy shelf, the shopper must depart the dairy area westward rather than continue farther east.",
    "abstraction": {
      "state_properties": {
        "at_dairy_shelf": "at(5,2)",
        "west_of_dairy": "at(4,2)"
      },
      "events": {
        "dairy_shelf_pickup": {
          "pre": {
            "and": [
              "at_dairy_shelf",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "depart_dairy_west": {
          "pre": {
            "and": [
              "at_dairy_shelf",
              "hasCart",
              "W"
            ]
          },
          "post": "west_of_dairy"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dairy_shelf_pickup",
      "discharge": "depart_dairy_west"
    }
  },
  {
    "id": "no_southbound_cart_in_interior_aisles",
    "text": "While pushing a cart in the interior shopping aisles, southbound movement is forbidden.",
    "abstraction": {
      "state_properties": {
        "interior_shopping_aisle": {
          "or": [
            "at(1,2)",
            "at(1,3)",
            "at(1,4)",
            "at(2,2)",
            "at(2,3)",
            "at(2,4)",
            "at(3,2)",
            "at(3,3)",
            "at(3,4)",
            "at(4,2)",
            "at(4,3)",
            "at(4,4)",
            "at(5,2)",
            "at(5,3)",
            "at(5,4)",
            "at(6,2)",
            "at(6,3)",
            "at(6,4)",
            "at(7,2)",
            "at(7,3)",
            "at(7,4)",
            "at(8,2)",
            "at(8,3)",
            "at(8,4)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "southbound_cart_move_in_interior": {
          "pre": {
            "and": [
              "interior_shopping_aisle",
              "pushing_cart",
              "S"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "southbound_cart_move_in_interior"
    }
  }
]
